import React, { useState } from 'react';
import { useAuth } from '../contexts/AuthContext';
import './Login.css';

function Login() {
  const [usuario, setUsuario] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [showForgot, setShowForgot] = useState(false);
  const [resetEmail, setResetEmail] = useState('');
  const [resetMessage, setResetMessage] = useState('');
  const { login } = useAuth();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    const result = await login(usuario, password);
    if (!result.success) {
      setError(result.error);
    }
    setLoading(false);
  };

  const handleForgotPassword = async (e) => {
    e.preventDefault();
    if (!resetEmail) {
      setResetMessage('Ingresa tu correo electrónico');
      return;
    }
    setLoading(true);
    try {
      setResetMessage('Si el correo está registrado, recibirás instrucciones para recuperar tu contraseña.');
      setTimeout(() => {
        setShowForgot(false);
        setResetMessage('');
        setResetEmail('');
      }, 3000);
    } catch (error) {
      setResetMessage('Error al enviar el correo. Intenta de nuevo.');
    }
    setLoading(false);
  };

  return (
    <div className="login-container">
      <div className="login-card">
        <div className="login-header">
          <div className="logo-icon">
            <i className="fas fa-futbol"></i>
          </div>
          <h1>Academia Miguel Villalta</h1>
          <p>Formando campeones dentro y fuera de la cancha</p>
        </div>

        {!showForgot ? (
          <form onSubmit={handleSubmit} className="login-form">
            <div className="input-group">
              <i className="fas fa-id-card"></i>
              <input
                type="text"
                placeholder="Usuario o Correo electrónico"
                value={usuario}
                onChange={(e) => setUsuario(e.target.value)}
                required
                autoComplete="username"
              />
            </div>

            <div className="input-group">
              <i className="fas fa-lock"></i>
              <input
                type="password"
                placeholder="Contraseña"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
                autoComplete="current-password"
              />
            </div>

            {error && <div className="error-message">{error}</div>}

            <button type="submit" className="login-btn" disabled={loading}>
              {loading ? <i className="fas fa-spinner fa-spin"></i> : 'Iniciar Sesión'}
            </button>

            <div className="login-links">
              <button 
                type="button" 
                className="forgot-link"
                onClick={() => setShowForgot(true)}
              >
                ¿Olvidaste tu contraseña?
              </button>
            </div>
          </form>
        ) : (
          <form onSubmit={handleForgotPassword} className="login-form">
            <div className="input-group">
              <i className="fas fa-envelope"></i>
              <input
                type="email"
                placeholder="Correo electrónico"
                value={resetEmail}
                onChange={(e) => setResetEmail(e.target.value)}
                required
              />
            </div>

            {resetMessage && (
              <div className={`reset-message ${resetMessage.includes('Si el correo') ? 'success' : 'error'}`}>
                {resetMessage}
              </div>
            )}

            <button type="submit" className="login-btn" disabled={loading}>
              {loading ? <i className="fas fa-spinner fa-spin"></i> : 'Recuperar Contraseña'}
            </button>

            <div className="login-links">
              <button 
                type="button" 
                className="back-link"
                onClick={() => {
                  setShowForgot(false);
                  setResetMessage('');
                  setResetEmail('');
                }}
              >
                ← Volver al inicio de sesión
              </button>
            </div>
          </form>
        )}

        <div className="login-footer">
          <p className="contacto-info">
            <i className="fas fa-phone-alt"></i> +506 8641 6701
          </p>
        </div>
      </div>
    </div>
  );
}

export default Login;
